class Solution {
  public double minmaxGasDist(int[] stations, int k) {
    double lo = 0, hi = 1e8;
    // binary search the penalty: stations needed for gap g is ceil(g / d) - 1
    while (hi - lo > 1e-6) {
      double mid = (lo + hi) / 2;
      long needed = 0;
      for (int i = 1; i < stations.length; i++) needed += (long) ((stations[i] - stations[i - 1]) / mid);
      if (needed <= k) hi = mid;
      else lo = mid;
    }
    return hi;
  }
}
